import logging
import traceback
from functools import wraps
from taf.ue.spark.client.exception import CommandStateError


def decorate_command_with_response_state_check(func):
    @wraps(func)
    def wrapped(*args, **kwargs):
        try:
            command_result = func(*args, **kwargs)
            if command_result.bean.Param.State:
                raise CommandStateError("state {} is not success".format(command_result.bean.Param.State))
            return command_result
        except Exception as e:
            logging.debug("Exception {e} in {func}, stack is : {stack}".
                          format(e=e, func=func.__name__, stack=traceback.format_exc()))
            raise
    return wrapped
